def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    decrease = v1 - v2
    change_ratio = decrease / v1
    percentage_decrease = change_ratio * 100

    return {
        "value": percentage_decrease,
        "trace": {
            "initial_value": v1,
            "final_value": v2,
            "decrease": decrease,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
